package kernels

import (
	"math"
	"os"
)

// loong64 LASX kernels generated by go-asmgen (sum_loong64.s). LASX (256-bit,
// four float64 lanes) is not on every LoongArch CPU, so each wrapper uses it
// only when the kernel reports it in AT_HWCAP, and runs the scalar oracle
// otherwise.
//
//go:generate sh -c "cd asmgen/loong64 && go run . && mv sum_loong64.s ../../sum_loong64.s"

// HaveReduceSIMD reports that this build ships SIMD kernels; they run when
// useLASX is true.
const HaveReduceSIMD = true

// hwcapLASX is HWCAP_LOONGARCH_LASX (Linux arch/loongarch/include/uapi/asm/hwcap.h).
const hwcapLASX = 1 << 5

// useLASX selects the LASX kernels. A var so tests can force the scalar path
// on hardware that has LASX (never the reverse: that would fault).
var useLASX = lasxFromAuxv()

func lasxFromAuxv() bool {
	auxv, err := os.ReadFile("/proc/self/auxv")
	return err == nil && hwcapFrom(auxv)&hwcapLASX != 0
}

// The sum is floats.SumPairwise on every target (reduce_sum.go): NumPy's order.
// The elementwise kernels and sqrt are go-simd/floats' (reduce_floats_elem.go).

// max/min stay on the four-accumulator scalar reducers.
// maxSIMD / minSIMD reduce whole blocks of 8 with the LSX kernels
// (sum_loong64.s), which work on the floats' bits mapped to an integer order
// (see fromOrdered64) because Go's loong64 assembler has no vector float max.
// The wrapper maps the two lanes back and folds them and the tail with Go's
// max/min; a NaN anywhere, reported by the kernel, is NaN.
func maxSIMD(a []float64) float64 {
	n := len(a) &^ 7
	if !useLASX || n == 0 {
		return maxUnrolled(a)
	}
	var out [2]int64
	if maxLSX(&a[0], n, &out) != 0 {
		return math.NaN()
	}
	m := max(fromOrdered64(out[0]), fromOrdered64(out[1]))
	for _, v := range a[n:] {
		m = max(m, v)
	}
	return m
}

func minSIMD(a []float64) float64 {
	n := len(a) &^ 7
	if !useLASX || n == 0 {
		return minUnrolled(a)
	}
	var out [2]int64
	if minLSX(&a[0], n, &out) != 0 {
		return math.NaN()
	}
	m := min(fromOrdered64(out[0]), fromOrdered64(out[1]))
	for _, v := range a[n:] {
		m = min(m, v)
	}
	return m
}

// fromOrdered64 undoes the kernels' order map t = x XOR ((x >>a 63) >>l 1),
// which is its own inverse.
func fromOrdered64(t int64) float64 {
	return math.Float64frombits(uint64(t ^ int64(uint64(t>>63)>>1)))
}

//go:noescape
func maxLSX(a *float64, n int, out *[2]int64) int64

//go:noescape
func minLSX(a *float64, n int, out *[2]int64) int64
